mkdir -p /tmp/bot-check && cat > /tmp/bot-check/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g5-2/bot.mjs';

let n = 0;
const t = (name, fn) => { fn(); n++; console.log('ok -', name); };
const H = 60 * 60 * 1000;
let uid = 0;
const fresh = () => `u${++uid}`;
const T0 = new Date('2026-10-23T10:00:00Z');
const at = (ms) => new Date(T0.getTime() + ms);

t('never-contacted customer: freeform and template both blocked', () => {
  const u = fresh();
  assert.deepEqual(check(u, 'freeform', at(0)), { allowed: false, rule: 'no-prior-inbound' });
  assert.deepEqual(check(u, 'template', at(0)), { allowed: false, rule: 'no-prior-inbound' });
});

t('freeform allowed within 24h of last inbound, blocked at and after 24h', () => {
  const u = fresh();
  onInbound(u, 'hi, my bill is wrong', at(0));
  assert.deepEqual(check(u, 'freeform', at(23 * H)), { allowed: true, rule: null });
  assert.deepEqual(check(u, 'freeform', at(24 * H - 1)), { allowed: true, rule: null });
  assert.deepEqual(check(u, 'freeform', at(24 * H)), { allowed: false, rule: 'outside-24h-window' });
});

t('a newer inbound reopens the freeform window', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'still there?', at(30 * H));
  assert.equal(check(u, 'freeform', at(40 * H)).allowed, true);
});

t('template allowed outside the window once customer has written', () => {
  const u = fresh();
  onInbound(u, 'hello', at(0));
  assert.deepEqual(check(u, 'template', at(100 * H)), { allowed: true, rule: null });
});

t('unknown type is refused', () => {
  const u = fresh();
  onInbound(u, 'hello', at(0));
  assert.deepEqual(check(u, 'sms-blast', at(1)), { allowed: false, rule: 'unknown-type' });
});

const STOP_VARIANTS = ['STOP', 'stop', 'Stop.', ' stop! ', 'STOP!!!', 'stop 🛑', 'S​top', 'ＳＴＯＰ', 'Stop ', '"stop"', 'stop\n', 'Stopall', 'STOP ALL', 'unsubscribe', 'Cancel', 'END', 'quit', 'Stop texting me.', 'please stop messaging me’', 'Don’t text me'];
for (const v of STOP_VARIANTS) {
  t(`opt-out keyword ${JSON.stringify(v)}`, () => {
    const u = fresh();
    onInbound(u, 'hi', at(0));
    onInbound(u, v, at(1 * H));
    assert.deepEqual(check(u, 'freeform', at(2 * H)), { allowed: false, rule: 'opted-out' });
    assert.deepEqual(check(u, 'template', at(2 * H)), { allowed: false, rule: 'opted-out' });
  });
}

const NORMAL = ['please stop by the store tomorrow', 'stop charging me for this', 'Can you cancel my plan?', 'do not stop until it works', 'stop, my phone is broken', 'the end', 'Don\'t text me about the bill, call instead'];
for (const v of NORMAL) {
  t(`ordinary sentence is not an opt-out: ${JSON.stringify(v)}`, () => {
    const u = fresh();
    onInbound(u, v, at(0));
    assert.deepEqual(check(u, 'freeform', at(H)), { allowed: true, rule: null });
  });
}

t('a message after STOP that is not a start keyword does not re-subscribe', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'STOP', at(H));
  onInbound(u, 'actually I need help', at(2 * H));
  assert.deepEqual(check(u, 'template', at(3 * H)), { allowed: false, rule: 'opted-out' });
});

const START_VARIANTS = ['START', 'start', 'Start!', 'UNSTOP', 'unstop.', 'start again', 'Start Again'];
for (const v of START_VARIANTS) {
  t(`start keyword ${JSON.stringify(v)} restores messaging`, () => {
    const u = fresh();
    onInbound(u, 'hi', at(0));
    onInbound(u, 'STOP', at(H));
    onInbound(u, v, at(2 * H));
    assert.deepEqual(check(u, 'template', at(3 * H)), { allowed: true, rule: null });
    assert.deepEqual(check(u, 'freeform', at(3 * H)), { allowed: true, rule: null });
  });
}

t('"yes" alone does not restore messaging', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'STOP', at(H));
  onInbound(u, 'YES', at(2 * H));
  assert.equal(check(u, 'template', at(3 * H)).rule, 'opted-out');
});

t('out-of-order delivery: older START does not undo a newer STOP', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'STOP', at(5 * H));
  onInbound(u, 'START', at(2 * H));
  assert.equal(check(u, 'template', at(6 * H)).rule, 'opted-out');
});

t('same-instant STOP and START: stop wins', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'START', at(H));
  onInbound(u, 'STOP', at(H));
  assert.equal(check(u, 'template', at(2 * H)).rule, 'opted-out');
});

t('opt-out state is per customer', () => {
  const a = fresh(), b = fresh();
  onInbound(a, 'hi', at(0));
  onInbound(b, 'hi', at(0));
  onInbound(a, 'STOP', at(H));
  assert.equal(check(a, 'template', at(2 * H)).rule, 'opted-out');
  assert.deepEqual(check(b, 'template', at(2 * H)), { allowed: true, rule: null });
});

t('invalid Date throws instead of silently recording', () => {
  assert.throws(() => onInbound(fresh(), 'STOP', new Date('nope')), TypeError);
  assert.throws(() => check(fresh(), 'template', '2026-10-23'), TypeError);
});

console.log(`\n${n} checks passed`);
EOF
node /tmp/bot-check/test.mjs
